import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"25、【无妄】 震下乾上","description":"周易口诀义 - 25、【无妄】 震下乾上","frontmatter":{"title":"25、【无妄】 震下乾上","description":"周易口诀义 - 25、【无妄】 震下乾上"},"headers":[],"relativePath":"zh/classics/koujueyi/027.md","filePath":"zh/classics/koujueyi/027.md"}'),r={name:"zh/classics/koujueyi/027.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_25、【无妄】-震下乾上" tabindex="-1">25、【无妄】 震下乾上 <a class="header-anchor" href="#_25、【无妄】-震下乾上" aria-label="Permalink to “25、【无妄】 震下乾上”">​</a></h1><p>彖曰：无妄，刚自外来而为主于内，动而健，刚中而应，大亨以正，天之命也。「其匪正有眚，不利有攸往」，无妄之往，何之矣？天命不祐，行矣哉！</p><p>象曰：天下雷行，物与无妄。先王以茂对时育万物。</p><p>初九：无妄，往吉。象曰：「无妄」之往，得志也。</p><p>六二：不耕获，不菑畬，则利有攸往。</p><p>象曰：「不耕获」，未富也。</p><p>六三：无妄之灾，或系之牛，行人之得，邑人之灾。</p><p>象曰：行人得牛，邑人灾也。</p><p>九四：可贞，无咎。</p><p>象曰：「可贞无咎」，固有之也。</p><p>九五：无妄之疾，勿药有喜。</p><p>象曰：「无妄」之药，不可试也。</p><p>上九：无妄行有眚，无攸利。</p><p>象曰：「无妄」之行，穷之灾也。</p><p>无（四库全书标明，摘录时缺豫、随、无妄、大壮、晋、睽、蹇、解、中孚八卦）</p>',15)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
